'use strict';
const $=id=>document.getElementById(id), audio=$('audio');
const defaults={shows:{},episodes:{},queue:[],current:null,positions:{},played:{},favorites:{},bookmarks:[],settings:{speed:1,back:15,forward:30,queueRule:'last',autoDownload:false,cleanup:false,proxy:'',hidePlayed:false,episodeSort:'newest'},downloads:{}};
let S;try{S={...defaults,...JSON.parse(localStorage.getItem('podflow-v1')||'{}')};S.settings={...defaults.settings,...S.settings}}catch{S=structuredClone(defaults)}
let page='Home',filter='All',searchResults=[],busy=false,sleepEnd=0,sleepEpisode=false,activeURL='',lastSave=0,loadToken=0,selectedShow=null,toastTimer;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=x=>{try{let u=new URL(x,location.href);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const fmt=n=>{n=Math.max(0,Math.floor(Number(n)||0));return (n>=3600?Math.floor(n/3600)+':':'')+String(Math.floor(n/60)%60).padStart(n>=3600?2:1,'0')+':'+String(n%60).padStart(2,'0')};
const save=()=>{try{localStorage.setItem('podflow-v1',JSON.stringify(S))}catch{toast('Storage is full. Export a backup.')}};
function toast(t){$('status').textContent=t;$('fullStatus').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('status').textContent='';$('fullStatus').textContent=''},6500)}
function art(e){const url=safeURL(e?.art);return url?`<img class="art" src="${esc(url)}" alt="" loading="lazy" onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'art',textContent:'♫'}))">`:'<div class="art">♫</div>'}
function idFor(s){let h=2166136261;for(const c of s){h=Math.imul(h^c.charCodeAt(0),16777619)}return 'p'+(h>>>0).toString(36)}
function togglePlayedVisibility(){S.settings.hidePlayed=!S.settings.hidePlayed;if(S.settings.hidePlayed&&filter==='Played')filter='All';save();render()}
function playedToggle(){return `<button aria-pressed="${S.settings.hidePlayed}" class="${S.settings.hidePlayed?'primary':''}" onclick="togglePlayedVisibility()">${S.settings.hidePlayed?'✓ Hide played':'Hide played'}</button>`}
function markPlayed(id){if(!S.episodes[id])return;const played=!S.played[id];if(played){S.played[id]=Date.now();S.positions[id]=0;S.queue=S.queue.filter(x=>x!==id)}else{delete S.played[id];S.positions[id]=0}save();render();toast(played?'Marked as played':'Marked as unplayed')}
function setEpisodeSort(value){S.settings.episodeSort=value==='oldest'?'oldest':'newest';save();render()}
function sortControl(){return `<label>Sort: <select aria-label="Sort episodes" onchange="setEpisodeSort(this.value)"><option value="newest" ${S.settings.episodeSort!=='oldest'?'selected':''}>Newest first</option><option value="oldest" ${S.settings.episodeSort==='oldest'?'selected':''}>Oldest first</option></select></label>`}
function sortEpisodes(es){return [...es].sort((a,b)=>{const ad=Number(a.date)||0,bd=Number(b.date)||0;if(!ad||!bd)return Number(!ad)-Number(!bd);return S.settings.episodeSort==='oldest'?ad-bd:bd-ad})}
function goDownloads(){page='Episodes';selectedShow=null;filter='Downloaded';render()}
function downloadButton(e){return S.downloads[e.id]?`<button class="small" title="Remove offline copy" onclick="removeDownload('${e.id}')">✓ Offline</button>`:e.url?`<button class="small" ${downloading.has(e.id)?'disabled':''} onclick="downloadEpisode('${e.id}')">${downloading.has(e.id)?'Downloading '+(downloadProgress[e.id]||'…'):'↓ Download'}</button>`:''}
function go(p){page=p;selectedShow=null;render();if(p==='Discover')loadRecommendations()}
function render(){const pages=['Home','Discover','Library','Episodes','Bookmarks','Settings'];$('nav').innerHTML=pages.map(p=>`<button class="${page===p?'active':''}" onclick="go('${p}')">${({Home:'⌂',Discover:'⌕',Library:'▤',Episodes:'☷',Bookmarks:'☆',Settings:'⚙'})[p]} &nbsp;${p}</button>`).join('');let h='';const es=Object.values(S.episodes).sort((a,b)=>(b.date||0)-(a.date||0));const shows=Object.values(S.shows);if(page==='Home'){h=`<h1>Good to hear you.</h1><section class="section"><h2>Continue listening</h2><div class="toolbar"><button onclick="goDownloads()">↓ Downloads (${Object.keys(S.downloads).length})</button></div>${episodeList(es.filter(e=>S.positions[e.id]>0&&!S.played[e.id]).slice(0,5))}</section><section class="section"><h2>Your shows</h2>${showCards(shows)}</section><div class="hero"><span>YOUR PERSONAL PODCAST SPACE</span><h2>Find your next favorite.</h2><p>More stories. Less silence. Listen on your terms.</p><div><button class="primary" onclick="go('Discover')">Explore podcasts</button></div></div>`}else if(page==='Discover'){h=`<h1>Discover</h1><p class="muted">Search the Apple Podcasts directory or add a feed.</p><div id="recommendations">${recommendationHTML()}</div><form class="toolbar" onsubmit="event.preventDefault();discover(this.q.value)"><input name="q" placeholder="Search podcasts" required><button class="primary">Search</button></form><form class="toolbar" onsubmit="event.preventDefault();subscribe(this.url.value)"><input name="url" type="url" placeholder="Paste public or private RSS URL" required><button>Add RSS</button></form><div class="toolbar"><button onclick="localAudio()">Open local audio</button><button onclick="directAudio()">Add audio URL</button></div><div class="cards">${searchResults.map((s,i)=>`<article class="card">${art(s)}<h3>${esc(s.title)}</h3><small>${esc(s.author)}</small><button onclick="subscribeResult(${i})">Subscribe</button></article>`).join('')}</div>`}else if(page==='Library'){h=`<h1>Your library</h1><div class="toolbar"><button onclick="refreshAll()">Refresh feeds</button><button onclick="go('Discover')">Add show</button></div>${selectedShow&&S.shows[selectedShow]?`<button onclick="selectedShow=null;render()">← All shows</button><h2 class="section">${esc(S.shows[selectedShow].title)}</h2><div class="toolbar"><button onclick="showSettings('${selectedShow}')">Show settings</button><button onclick="refreshShow('${selectedShow}')">Refresh</button>${playedToggle()}${sortControl()}<button onclick="unsubscribe('${selectedShow}')">Unsubscribe</button></div>${episodeList(sortEpisodes(es.filter(e=>e.show===selectedShow&&(!S.settings.hidePlayed||!S.played[e.id]))))}`:showCards(shows)}`}else if(page==='Episodes'){const filters=['All','Unplayed','Under 30 min','Downloaded','Favorites','News','Played'];let list=es.filter(e=>filter==='All'||filter==='Unplayed'&&!S.played[e.id]||filter==='Under 30 min'&&!S.played[e.id]&&e.length>0&&e.length<1800||filter==='Downloaded'&&S.downloads[e.id]||filter==='Favorites'&&S.favorites[e.id]||filter==='News'&&/news|urgent/i.test(e.title+' '+(S.shows[e.show]?.category||''))||filter==='Played'&&S.played[e.id]);h=`<h1>Episodes</h1>${filter==='Downloaded'?`<div class="notice">${Object.keys(S.downloads).length} saved episodes · ${(Object.values(S.downloads).reduce((n,d)=>n+(d.size||0),0)/1048576).toFixed(1)} MB on this device. Open PodFlow while online before traveling, then use this list offline.</div>`:''}<div class="toolbar">${playedToggle()}${sortControl()}</div><div class="toolbar">${filters.map(f=>`<button class="${filter===f?'primary':''}" onclick="filter='${f}';render()">${f}</button>`).join('')}</div><input style="width:100%" placeholder="Filter episode titles" oninput="document.querySelectorAll('#episodeResults .episode').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(this.value.toLowerCase()))"><div id="episodeResults">${episodeList(sortEpisodes(list.filter(e=>filter==='Played'||filter==='Downloaded'||!S.settings.hidePlayed||!S.played[e.id])))}</div>`}else if(page==='Bookmarks'){h=`<h1>Bookmarks</h1>${S.bookmarks.length?S.bookmarks.map((b,i)=>`<div class="episode"><div class="info"><h3>${esc(S.episodes[b.id]?.title||'Episode')}</h3><small>${fmt(b.time)} • ${esc(b.note)}</small></div><button onclick="playEpisode('${b.id}',${b.time})">Play</button><button onclick="S.bookmarks.splice(${i},1);save();render()">Delete</button></div>`).join(''):'<p class="empty">Save moments while listening using the star in the player.</p>'}`}else if(page==='Settings'){h=`<h1>Settings</h1><div class="section settings"><h2>Playback</h2>${settingNumber('Default speed','speed',.5,3,.05)}${settingNumber('Back skip (seconds)','back',5,120,1)}${settingNumber('Forward skip (seconds)','forward',5,300,1)}<label class="setting">New episodes on refresh<select onchange="setSetting('queueRule',this.value)">${[['none','Do not queue'],['next','Play next'],['last','Play last'],['now','Interrupt playback']].map(([v,l])=>`<option value="${v}" ${S.settings.queueRule===v?'selected':''}>${l}</option>`).join('')}</select></label>${settingCheck('Prefetch next episode on reported Wi-Fi','autoDownload')}${settingCheck('Delete played downloads after 24 hours','cleanup')}<div class="notice">Smart silence trimming and voice leveling require accessible audio processing and are not included in this version. Pitch preservation uses the browser audio engine.</div><h2>RSS access</h2><p class="muted">Some podcast servers block browser requests. An optional trusted CORS proxy can be configured for public feeds only. Never send private subscription URLs through an untrusted proxy.</p><input placeholder="Optional proxy URL prefix, ending in ?url=" value="${esc(S.settings.proxy)}" onchange="setSetting('proxy',this.value)"><h2>Library & backup</h2><div class="toolbar"><button onclick="importOPML()">Import OPML</button><button onclick="exportOPML()">Export OPML</button><button onclick="backup()">Export backup</button><button onclick="restore()">Restore backup</button></div><p class="muted">Backups can contain private RSS tokens. Keep them secure. Audio downloads are not included. Cross-device automatic sync is not configured.</p></div>`}$('view').innerHTML=h;renderQueue();renderPlayer()}
function settingNumber(label,k,min,max,step){return `<label class="setting">${label}<input type="number" min="${min}" max="${max}" step="${step}" value="${S.settings[k]}" onchange="setSetting('${k}',Math.min(${max},Math.max(${min},Number(this.value)||${min})))"></label>`}
function settingCheck(label,k){return `<label class="setting">${label}<input type="checkbox" ${S.settings[k]?'checked':''} onchange="setSetting('${k}',this.checked)"></label>`}
function setSetting(k,v){S.settings[k]=v;save();if(k==='speed')applyRate(v);renderPlayer();if(k==='cleanup')cleanup();if(k==='autoDownload')prefetch()}
function showCards(shows){return shows.length?`<div class="cards">${shows.map(s=>`<article class="card">${art(s)}<h3>${esc(s.title)}</h3><small>${Object.values(S.episodes).filter(e=>e.show===s.id&&!S.played[e.id]).length} unplayed</small><button onclick="page='Library';selectedShow='${s.id}';render()">View show</button></article>`).join('')}</div>`:'<p class="empty">No subscriptions yet. Discover a show or add an RSS feed.</p>'}
function episodeList(es){return es.length?es.map(e=>`<article class="episode compact-episode">${art(e)}<div class="info"><h3>${esc(e.title)}</h3><small>${esc(S.shows[e.show]?.title||'Local audio')} ${e.date?' • '+esc(new Date(e.date).toLocaleDateString()):''} ${e.length?' • '+fmt(e.length):''} ${S.played[e.id]?' • Played':''} ${S.downloads[e.id]?' • ✓ Offline':downloading.has(e.id)?' • Downloading '+esc(downloadProgress[e.id]||'…'):''}</small></div><button class="episode-more" aria-label="Episode options" aria-haspopup="dialog" onclick="episodeMenu('${e.id}')">⋯</button></article>`).join(''):'<p class="empty">Nothing here yet.</p>'}
function modal(h){$('modal').dataset.kind='';$('modal').innerHTML='<button class="small close" onclick="closeModal()">✕</button>'+h;if(!$('modal').open)$('modal').showModal()}
function fullPlayerMoreMenu(){const e=S.episodes[S.current],rate=(audio.src?audio.playbackRate:S.settings.speed).toFixed(2);modal(`<h2>Playback options</h2><div class="settings section episode-options"><button onclick="speedDialog()">Speed (${rate}×)</button><button onclick="sleepDialog()">◷ Sleep timer</button><button onclick="bookmark()">☆ Bookmark</button><button onclick="openDetails()">Show notes</button>${e?.url?`<button ${downloading.has(e.id)?'disabled':''} onclick="closeModal();${S.downloads[e.id]?'toast(\'Available offline\')':"downloadEpisode('"+e.id+"')"}">${S.downloads[e.id]?'✓ Available offline':downloading.has(e.id)?'Downloading…':'↓ Download episode'}</button>`:''}</div>`)}
function closeModal(){$('modal').close()}
function episodeMenu(id){let e=S.episodes[id];if(!e)return;modal(`<h2>${esc(e.title)}</h2><div class="settings section episode-options"><button class="primary" onclick="closeModal();playEpisode('${id}')">▶ Play now</button><button onclick="enqueue('${id}','next');closeModal()">Play next</button><button onclick="enqueue('${id}','last');closeModal()">Play last</button><button onclick="markPlayed('${id}');closeModal()">${S.played[id]?'Mark unplayed':'✓ Mark played'}</button>${e.url?`<button ${downloading.has(id)?'disabled':''} onclick="closeModal();${S.downloads[id]?`removeDownload('${id}')`:`downloadEpisode('${id}')`}">${S.downloads[id]?'Remove download':downloading.has(id)?'Downloading…':'↓ Download episode'}</button>`:''}<button onclick="S.favorites['${id}']=!S.favorites['${id}'];save();render();closeModal()">${S.favorites[id]?'Remove favorite':'☆ Add favorite'}</button><button onclick="openDetails('${id}')">Show notes & chapters</button><button onclick="openTranscript('${id}')">Transcript / Generate</button></div>`)}

const genreMap={'arts':1301,'business':1321,'comedy':1303,'education':1304,'fiction':1483,'government':1511,'history':1487,'health & fitness':1512,'kids & family':1305,'leisure':1502,'music':1310,'news':1489,'religion & spirituality':1314,'science':1533,'society & culture':1324,'sports':1545,'technology':1318,'true crime':1488,'tv & film':1309};
const normalizeRec=s=>String(s||'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function recGenres(show){const raw=[show.category,...(show.genres||[])].filter(Boolean).map(x=>String(x).toLowerCase());return Object.keys(genreMap).filter(g=>raw.some(x=>x===g||x.includes(g)))}
let recItems=[],recLoading=false,recError='',recKey='',recOffset=0,recTime=0;
function libraryRecKey(){return Object.values(S.shows).map(x=>x.id+':'+x.category+':'+(x.genres||[]).join(',')).sort().join('|')}
async function recJSON(url){const c=new AbortController(),timer=setTimeout(()=>c.abort(),12000);try{const r=await fetch(url,{credentials:'omit',signal:c.signal,referrerPolicy:'no-referrer'});if(!r.ok)throw Error('Directory unavailable');return await r.json()}finally{clearTimeout(timer)}}
function recAvailable(){const shows=Object.values(S.shows),names=new Set(shows.map(s=>normalizeRec(s.title))),feeds=new Set(shows.map(s=>s.feed));return recItems.filter(s=>!names.has(normalizeRec(s.title))&&!feeds.has(s.feed))}
function recommendationHTML(){const available=recAvailable();const visible=available.length?Array.from({length:Math.min(6,available.length)},(_,i)=>available[(recOffset+i)%available.length]):[];return '<section class="rec-panel"><div class="rec-head"><div><span class="rec-kicker">✦ DISCOVER SOMETHING NEW</span><h2>'+ (Object.keys(S.shows).length?'Recommended for you':'Popular podcasts')+'</h2></div><button class="small" onclick="moreRecommendations()" aria-label="More recommendations">↻ More</button></div><p class="rec-sub">'+(Object.values(S.shows).some(s=>recGenres(s).length)?'Popular shows matched to your library’s topics.':'Trending US shows — add categorized podcasts for personalized matches.')+'</p>'+(recLoading?'<p class="rec-sub">Finding popular podcasts…</p>':'')+(visible.length?'<div class="rec-strip">'+visible.map(s=>'<article class="rec-card">'+art(s)+'<h3>'+esc(s.title)+'</h3><small>'+esc(s.category||'Podcast')+'</small><span class="rec-rank">'+esc(s.rankLabel)+'</span><button class="small" onclick="subscribeRecommendation('+recItems.indexOf(s)+')">＋ Subscribe</button></article>').join('')+'</div>':!recLoading?'<p class="rec-sub">'+esc(recError||'No matching chart shows found. Try again later.')+'</p>':'')+'</section>'}
function renderRecommendations(){const el=$('recommendations');if(el)el.innerHTML=recommendationHTML()}
function moreRecommendations(){if(recAvailable().length>6){recOffset=(recOffset+6)%recAvailable().length;renderRecommendations()}else loadRecommendations(true)}
async function subscribeRecommendation(i){const s=recItems[i];if(s&&await subscribe(s.feed,{...s,publicDirectory:true})){recKey='';loadRecommendations(true)}}
async function loadRecommendations(force=false){const key=libraryRecKey();if(recLoading)return;if(!force&&key===recKey&&Date.now()-recTime<3600000){renderRecommendations();return}recLoading=true;recError='';if(key!==recKey){recItems=[];recOffset=0}renderRecommendations();try{
 const shows=Object.values(S.shows),weights={};for(const s of shows)for(const g of recGenres(s))weights[g]=(weights[g]||0)+1;
 const genres=Object.keys(weights).sort((a,b)=>weights[b]-weights[a]).slice(0,3);
 const jobs=genres.map(g=>({g,url:'https://itunes.apple.com/us/rss/toppodcasts/limit=50/genre='+genreMap[g]+'/json'}));jobs.push({g:null,url:'https://rss.marketingtools.apple.com/api/v2/us/podcasts/top/100/podcasts.json'});
 const charts=await Promise.allSettled(jobs.map(async j=>({g:j.g,data:await recJSON(j.url)})));
 const ranked=new Map();for(const result of charts){if(result.status!=='fulfilled')continue;const {g,data}=result.value;const list=data.feed?.entry||data.feed?.results||[];list.forEach((x,i)=>{const id=String(x.id?.attributes?.['im:id']||x.id||'');if(!/^\d+$/.test(id))return;const rank=i+1,score=(g?120+(weights[g]||1)*10:20)-rank*.5;const old=ranked.get(id);if(!old||score>old.score)ranked.set(id,{id,g,rank,score})})}
 if(!ranked.size)throw Error('Apple podcast charts are unavailable. Tap More to retry.');
 const candidates=[...ranked.values()].sort((a,b)=>b.score-a.score).slice(0,100);
 const details=await Promise.allSettled(Array.from({length:Math.ceil(candidates.length/25)},(_,i)=>recJSON('https://itunes.apple.com/lookup?country=us&entity=podcast&id='+candidates.slice(i*25,i*25+25).map(x=>x.id).join(','))));
 const found=[];for(const d of details)if(d.status==='fulfilled')for(const x of d.value.results||[]){const r=ranked.get(String(x.collectionId||x.trackId));if(!r||!x.feedUrl)continue;const cats=recGenres({category:x.primaryGenreName,genres:x.genres});const matched=cats.filter(g=>weights[g]);if(shows.length&&genres.length&&!r.g&&!matched.length)continue;found.push({title:x.collectionName||x.trackName,author:x.artistName,art:x.artworkUrl600||x.artworkUrl100,feed:x.feedUrl,category:x.primaryGenreName||r.g,genres:x.genres||[],score:r.score+matched.reduce((n,g)=>n+weights[g]*12,0),rankLabel:r.g?'#'+r.rank+' in '+(x.primaryGenreName||r.g):'#'+r.rank+' US chart'})}
 if(!found.length)throw Error('No matching chart results available. Tap More to retry.');
 const seen=new Set();recItems=found.sort((a,b)=>b.score-a.score).filter(x=>{const k=normalizeRec(x.title);if(seen.has(k))return false;seen.add(k);return true});recKey=key;recTime=Date.now();recOffset=0;
 if(shows.length&&!genres.length)recError='Library categories unavailable; showing popular US podcasts.';
 }catch(e){recError=e.message||'Recommendations unavailable';}finally{recLoading=false;renderRecommendations()}
}

async function discover(q){toast('Searching…');try{let r=await fetch('https://itunes.apple.com/search?media=podcast&entity=podcast&limit=36&term='+encodeURIComponent(q));if(!r.ok)throw Error('Search service unavailable');let j=await r.json();searchResults=j.results.filter(x=>x.feedUrl).map(x=>({title:x.collectionName,author:x.artistName,art:x.artworkUrl600||x.artworkUrl100,feed:x.feedUrl,category:x.primaryGenreName,genres:x.genres||[]}));render();toast(searchResults.length+' shows found')}catch(e){toast('Search failed. Try adding an RSS URL directly.')}}

async function fetchText(url,proxyAllowed=false){let u=safeURL(url);if(!u)throw Error('Invalid URL');try{let r=await fetch(u,{credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('HTTP '+r.status);return await r.text()}catch(e){if(!proxyAllowed||!S.settings.proxy)throw Error('Feed is unavailable or blocks browser requests (CORS).');let p=safeURL(S.settings.proxy+encodeURIComponent(u));if(!p)throw Error('Invalid proxy');let r=await fetch(p,{credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('Proxy failed');return r.text()}}
const child=(n,name)=>Array.from(n.children).find(c=>c.localName===name);const txt=(n,name)=>child(n,name)?.textContent?.trim()||'';const attr=(n,name,a)=>child(n,name)?.getAttribute(a)||'';
function seconds(s){return String(s||'').split(':').reduce((a,v)=>a*60+(Number(v)||0),0)}
async function subscribe(url,meta={},refresh=false,keepPlaying=false){if(busy){toast('A feed request is already running.');return false}let feed=safeURL(url);if(!feed){toast('Enter a valid HTTP(S) feed URL.');return false}busy=true;toast('Loading feed…');try{let id=idFor(feed);let xml=new DOMParser().parseFromString(await fetchText(feed,!!meta.publicDirectory),'application/xml');if(xml.querySelector('parsererror'))throw Error('Invalid RSS XML');let channel=xml.querySelector('channel');if(!channel)throw Error('RSS channel not found');let old=S.shows[id];let show={...old,id,feed,title:txt(channel,'title')||meta.title||'Podcast',art:attr(channel,'image','href')||txt(child(channel,'image')||channel,'url')||meta.art||'',category:meta.category||old?.category||attr(channel,'category','text')||txt(channel,'category'),genres:meta.genres||old?.genres||Array.from(channel.children).filter(x=>x.localName==='category').map(x=>x.getAttribute('text')||x.textContent.trim()).filter(Boolean),publicDirectory:!!(meta.publicDirectory||old?.publicDirectory),settings:old?.settings||{}};S.shows[id]=show;let newIds=[];for(let item of Array.from(channel.children).filter(x=>x.localName==='item')){let enc=child(item,'enclosure');let media=safeURL(enc?.getAttribute('url'));if(!media)continue;let eid=idFor(id+'|'+(txt(item,'guid')||media));if(!S.episodes[eid])newIds.push(eid);S.episodes[eid]={id:eid,show:id,title:txt(item,'title')||'Untitled',url:media,art:attr(item,'image','href')||show.art,date:Date.parse(txt(item,'pubDate'))||0,length:seconds(txt(item,'duration')),notes:txt(item,'encoded')||txt(item,'description'),chapters:attr(item,'chapters','url'),transcript:attr(item,'transcript','url'),transcriptType:attr(item,'transcript','type')}}if(old&&refresh&&newIds.length){let rule=show.settings.queueRule||S.settings.queueRule;if(keepPlaying&&rule==='now'&&S.current)rule='next';if(rule==='now'){for(let x of newIds.slice(1).reverse())enqueue(x,'next',false);playEpisode(newIds[0])}else if(rule!=='none'){for(let x of (rule==='next'?[...newIds].reverse():newIds))enqueue(x,rule,false)}}save();render();toast(`${show.title}: ${newIds.length} new episodes`);return true}catch(e){toast(e.message);return false}finally{busy=false}}
async function subscribeResult(i){let s=searchResults[i];if(s&&await subscribe(s.feed,{...s,publicDirectory:true}))loadRecommendations(true)}
function refreshShow(id){let s=S.shows[id];return s&&subscribe(s.feed,s,true)}async function refreshAll(){for(let id of Object.keys(S.shows))if(S.shows[id].feed)await refreshShow(id)}
function unsubscribe(id){if(!confirm('Unsubscribe? Downloaded audio and episode history will remain.'))return;delete S.shows[id];selectedShow=null;save();render()}
function showSettings(id){let s=S.shows[id],v=s.settings||{};modal(`<h2>${esc(s.title)}</h2><form class="settings section" onsubmit="event.preventDefault();saveShowSettings('${id}',this)"><label class="setting">Speed (blank = global)<input name="speed" type="number" min="0.5" max="3" step="0.05" value="${v.speed||''}"></label><label class="setting">Intro skip seconds<input name="intro" type="number" min="0" max="3600" value="${v.intro||0}"></label><label class="setting">Outro skip seconds<input name="outro" type="number" min="0" max="3600" value="${v.outro||0}"></label><label class="setting">Keep latest downloaded episodes (0 = unlimited)<input name="keep" type="number" min="0" max="999" value="${v.keep||0}"></label><label class="setting">New episode queue<select name="rule">${[['','Global'],['none','Do not queue'],['next','Play next'],['last','Play last'],['now','Interrupt']].map(([a,b])=>`<option value="${a}" ${(v.queueRule||'')===a?'selected':''}>${b}</option>`).join('')}</select></label><button class="primary">Save</button></form>`)}
function saveShowSettings(id,f){S.shows[id].settings={speed:Number(f.speed.value)||0,intro:Number(f.intro.value)||0,outro:Number(f.outro.value)||0,keep:Number(f.keep.value)||0,queueRule:f.rule.value};save();closeModal();retention(id);toast('Show settings saved')}
function enqueue(id,where,draw=true){if(!S.episodes[id]||id===S.current)return;S.queue=S.queue.filter(x=>x!==id);where==='next'?S.queue.unshift(id):S.queue.push(id);save();if(draw){renderQueue();toast('Added to queue');prefetch()}}
function queueHTML(){return S.queue.length?S.queue.map((id,i)=>`<div class="queueitem"><h3>${esc(S.episodes[id]?.title||'Unavailable')}</h3><div class="actions"><button onclick="playEpisode('${id}')">▶</button><button onclick="moveQueue(${i},-1)">↑</button><button onclick="moveQueue(${i},1)">↓</button><button onclick="S.queue.splice(${i},1);save();renderQueue()">✕</button></div></div>`).join(''):'<p class="empty">Add episodes to build your queue.</p>'}
function renderQueue(){$('queue').innerHTML=queueHTML();if($('modal').open&&$('modal').dataset.kind==='queue')$('modalQueue').innerHTML=queueHTML()}
function showQueue(){modal('<h2>Up next</h2><div id="modalQueue">'+queueHTML()+'</div>');$('modal').dataset.kind='queue'}$('modal').addEventListener('close',()=>$('modal').dataset.kind='');
function moveQueue(i,d){let j=i+d;if(j<0||j>=S.queue.length)return;[S.queue[i],S.queue[j]]=[S.queue[j],S.queue[i]];save();renderQueue()}
function applyRate(v){audio.preservesPitch=true;audio.webkitPreservesPitch=true;audio.playbackRate=Math.max(.5,Math.min(3,v));$('rate').textContent=audio.playbackRate.toFixed(2)+'×'}
async function playEpisode(id,at,autoplay=true){let e=S.episodes[id];if(!e)return;const token=++loadToken;persistPosition();audio.pause();audio.removeAttribute('src');audio.load();if(activeURL){URL.revokeObjectURL(activeURL);activeURL=''}S.current=id;S.queue=S.queue.filter(x=>x!==id);let blob;try{blob=await getBlob(id)}catch{}if(token!==loadToken)return;if(!blob&&S.downloads[id]){delete S.downloads[id];save()}if(!blob&&navigator.onLine===false){toast('This episode is not stored offline. Download it while connected.');render();return}if(blob){activeURL=URL.createObjectURL(blob);audio.src=activeURL}else if(e.url){audio.src=e.url}else{toast('Local audio is missing. Re-import the file.');render();return}let st=S.shows[e.show]?.settings||{};let target=at??(S.positions[id]||st.intro||0);if(autoplay&&S.played[id])delete S.played[id];audio.onloadedmetadata=()=>{if(token!==loadToken)return;audio.currentTime=Math.min(target,Number.isFinite(audio.duration)?audio.duration:target);if(Number.isFinite(audio.duration)){e.length=audio.duration;save()}updateTime()};applyRate(st.speed||S.settings.speed);save();render();if(autoplay&&!document.body.classList.contains('driving')&&!($('modal').open&&$('modal').dataset.kind==='transcript'))expandPlayer(true);if(autoplay)try{await audio.play()}catch{toast('Playback did not start. Tap Play or check the audio URL.')}mediaMeta(e);prefetch()}
function togglePlay(){if(!audio.src){if(S.current)playEpisode(S.current);else toast('Choose an episode first.');return}if(audio.paused)audio.play().catch(()=>toast('Could not play this audio.'));else audio.pause()}
function skip(d){if(!audio.src)return;audio.currentTime=Math.max(0,Math.min(Number.isFinite(audio.duration)?audio.duration:Infinity,audio.currentTime+(d<0?-S.settings.back:S.settings.forward)))}
function persistPosition(){if(S.current&&audio.src&&Number.isFinite(audio.currentTime)){if(!S.played[S.current])S.positions[S.current]=audio.currentTime;save()}}
let fullArtKey='';
function expandPlayer(on){if(on&&!S.episodes[S.current]){toast('Choose an episode first.');return}if(on)document.body.classList.remove('driving');document.body.classList.toggle('now-expanded',on);$('fullPlayer').setAttribute('aria-hidden',String(!on));if(on){renderPlayer();$('fullCollapse').focus({preventScroll:true})}else $('now').focus({preventScroll:true})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('modal').open&&document.body.classList.contains('now-expanded'))expandPlayer(false)});
function renderFullPlayer(e){const key=e?.id+'|'+e?.art;if(fullArtKey!==key){$('fullArt').innerHTML=art(e);fullArtKey=key}$('fullTitle').textContent=e?.title||'Nothing playing';$('fullShow').textContent=S.shows[e?.show]?.title||'PodFlow';$('fullOffline').textContent=S.downloads[e?.id]?'✓ Available offline':'';$('fullBack').textContent='↶ '+S.settings.back;$('fullForward').textContent=S.settings.forward+' ↷';$('fullPlay').textContent=audio.paused?'▶':'Ⅱ';$('fullPlay').setAttribute('aria-label',audio.paused?'Play':'Pause');}
function renderPlayer(){syncMediaState();let e=S.episodes[S.current];$('now').innerHTML=art(e)+`<div style="min-width:0"><h3>${esc(e?.title||'Nothing playing')}</h3><small>${esc(S.shows[e?.show]?.title||'PodFlow')}</small></div>`;$('driveTitle').textContent=e?.title||'Nothing playing';$('back').textContent='↶ '+S.settings.back;$('forward').textContent=S.settings.forward+' ↷';$('play').textContent=audio.paused?'▶':'Ⅱ';$('drivePlay').textContent=audio.paused?'Play':'Pause';$('rate').textContent=(audio.src?audio.playbackRate:S.settings.speed) .toFixed(2)+'×';renderFullPlayer(e);updateTime()}
function updateTime(){followTranscript();$('elapsed').textContent=fmt(audio.currentTime);$('duration').textContent=fmt(audio.duration||S.episodes[S.current]?.length);$('seek').max=Number.isFinite(audio.duration)?audio.duration:100;$('seek').value=audio.currentTime||0;$('fullSeek').max=$('seek').max;$('fullSeek').value=$('seek').value;$('fullElapsed').textContent=fmt(audio.currentTime);$('fullRemaining').textContent='−'+fmt(Math.max(0,(audio.duration||S.episodes[S.current]?.length||0)-audio.currentTime));if('mediaSession'in navigator&&Number.isFinite(audio.duration)&&audio.duration>0)try{navigator.mediaSession.setPositionState({duration:audio.duration,position:Math.min(audio.currentTime,audio.duration),playbackRate:audio.playbackRate})}catch{}}
$('fullSeek').oninput=()=>{if(audio.src)audio.currentTime=Number($('fullSeek').value)};$('seek').oninput=()=>{if(audio.src)audio.currentTime=Number($('seek').value)};audio.addEventListener('timeupdate',()=>{updateTime();if(Date.now()-lastSave>3000){lastSave=Date.now();persistPosition()}let outro=S.shows[S.episodes[S.current]?.show]?.settings?.outro||0;if(outro>0&&Number.isFinite(audio.duration)&&audio.duration>outro&&audio.currentTime>=audio.duration-outro&&!audio.paused)finish()});audio.addEventListener('play',renderPlayer);audio.addEventListener('pause',()=>{persistPosition();renderPlayer()});audio.addEventListener('ended',finish);audio.addEventListener('error',()=>{if(audio.src)toast('Audio could not be loaded. Check the feed or file format.')});window.addEventListener('pagehide',persistPosition);
function finish(){let id=S.current;if(!id)return;audio.pause();S.played[id]=Date.now();S.positions[id]=0;save();if(sleepEpisode){sleepEpisode=false;toast('Sleep timer finished');render();return}let next=S.queue.shift();save();if(next)playEpisode(next,0);else render()}
function speedDialog(){modal(`<h2>Playback speed</h2><div class="section"><h1 id="speedValue">${(audio.src?audio.playbackRate:S.settings.speed).toFixed(2)}×</h1><input type="range" min="0.5" max="3" step="0.05" value="${audio.src?audio.playbackRate:S.settings.speed}" oninput="applyRate(Number(this.value));$('speedValue').textContent=Number(this.value).toFixed(2)+'×'"><div class="toolbar">${[.75,1,1.25,1.5,2,2.5,3].map(v=>`<button onclick="applyRate(${v});speedDialog()">${v}×</button>`).join('')}</div><button onclick="S.settings.speed=audio.playbackRate;save();closeModal()">Save as default</button></div>`)}
function sleepDialog(){modal(`<h2>Sleep timer</h2><p class="muted">${sleepEpisode?'End of episode':sleepEnd?fmt((sleepEnd-Date.now())/1000)+' remaining':'Not set'}</p><div class="settings section">${[15,30,45,60].map(n=>`<button onclick="setSleep(${n})">${n} minutes</button>`).join('')}<button onclick="setSleep(-1)">End of episode</button><button onclick="setSleep(0)">Cancel timer</button></div>`)}
function setSleep(n){sleepEpisode=n===-1;sleepEnd=n>0?Date.now()+n*60000:0;closeModal();toast(n===-1?'Sleep at end of episode':n?'Sleep timer set':'Sleep timer canceled')}
setInterval(()=>{if(sleepEnd&&Date.now()>=sleepEnd){sleepEnd=0;audio.pause();toast('Sleep timer finished')}},500);
function bookmark(){if(!S.current){toast('Choose an episode first');return}let id=S.current,t=audio.currentTime||0;modal(`<h2>Bookmark at ${fmt(t)}</h2><form class="settings section" onsubmit="event.preventDefault();saveBookmark('${id}',${t},this.note.value)"><input name="note" placeholder="Optional note"><button class="primary">Save bookmark</button></form>`)}
function saveBookmark(id,t,note){S.bookmarks.unshift({id,time:t,note,date:Date.now()});save();closeModal();render();toast('Bookmark saved')}
function drive(on){if(on&&document.body.classList.contains('now-expanded'))expandPlayer(false);document.body.classList.toggle('driving',on)}
function mediaMeta(e){if(!('mediaSession'in navigator)||!e)return;const ms=navigator.mediaSession;try{ms.metadata=new MediaMetadata({title:e.title,artist:S.shows[e.show]?.title||'PodFlow',album:'PodFlow',artwork:[{src:safeURL(e.art)||new URL('./podflow-icon.png',location.href).href}]})}catch{}const seek=t=>{if(!audio.src||!Number.isFinite(t))return;audio.currentTime=Math.max(0,Math.min(Number.isFinite(audio.duration)?audio.duration:Infinity,t));persistPosition()};const actions={play:()=>{if(audio.paused)togglePlay()},pause:()=>audio.pause(),stop:()=>{audio.pause();persistPosition()},seekbackward:d=>seek(audio.currentTime-(d?.seekOffset||S.settings.back)),seekforward:d=>seek(audio.currentTime+(d?.seekOffset||S.settings.forward)),seekto:d=>seek(d.seekTime),nexttrack:()=>{if(S.queue.length)playEpisode(S.queue[0]);else skip(1)},previoustrack:()=>skip(-1)};for(const [action,fn] of Object.entries(actions))try{ms.setActionHandler(action,fn)}catch{}syncMediaState()}
function syncMediaState(){if(!('mediaSession'in navigator))return;try{navigator.mediaSession.playbackState=!S.current||!audio.src?'none':audio.paused?'paused':'playing'}catch{}}
audio.addEventListener('playing',syncMediaState);audio.addEventListener('pause',syncMediaState);audio.addEventListener('ended',syncMediaState);audio.addEventListener('emptied',syncMediaState);
function sanitizedHTML(s){let doc=new DOMParser().parseFromString(s||'','text/html');let allowed=new Set(['P','BR','B','STRONG','I','EM','UL','OL','LI','A','H1','H2','H3','BLOCKQUOTE','DIV','SPAN']);function walk(n){if(n.nodeType===3){let text=n.textContent;return esc(text).replace(/\b(?:(\d+):)?(\d{1,2}):(\d{2})\b/g,(m,h,a,b)=>`<button class="small" onclick="jump(${Number(h||0)*3600+Number(a)*60+Number(b)})">${m}</button>`)}if(n.nodeType!==1)return '';if(['SCRIPT','STYLE','IFRAME','OBJECT'].includes(n.tagName))return '';let inner=Array.from(n.childNodes).map(walk).join('');if(!allowed.has(n.tagName))return inner;if(n.tagName==='A'){let u=safeURL(n.getAttribute('href'));return u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(n.textContent)}</a>`:inner}return `<${n.tagName.toLowerCase()}>${inner}</${n.tagName.toLowerCase()}>`}return Array.from(doc.body.childNodes).map(walk).join('')}

let transcriptJob=null,transcriptView=null,transcriptActive=null,transcriptFollow=true;
const transcriptKey=id=>'transcript:'+id;
async function storedTranscript(id){try{return await getBlob(transcriptKey(id))}catch{return null}}
function parseTranscript(raw){try{const j=JSON.parse(raw);const arr=Array.isArray(j)?j:j.segments||j.chunks||[];return arr.map(x=>({t:Number(x.startTime??x.start??x.timestamp?.[0])||0,text:String(x.body||x.text||'')})).filter(x=>x.text)}catch{return raw.replace(/\r/g,'').replace(/^WEBVTT[^\n]*\n/,'').split(/\n\s*\n/).filter(x=>x.trim()).map(x=>{const lines=x.split('\n'),i=lines.findIndex(l=>l.includes('-->'));return i<0?{t:null,text:x.trim()}:{t:seconds(lines[i].split('-->')[0].trim().replace(',','.')),text:lines.slice(i+1).join(' ').replace(/<[^>]*>/g,'')}}).filter(x=>x.text)}}
function transcriptStatus(id,msg){if(transcriptView===id&&$('txStatus'))$('txStatus').textContent=msg}
function followTranscript(){const box=$('txLines');if(!box||!$('modal').open||$('modal').dataset.kind!=='transcript')return;const current=transcriptView===S.current;$('txPlay').textContent=current&&!audio.paused?'Ⅱ':'▶';$('txPlay').setAttribute('aria-label',current&&!audio.paused?'Pause':'Play');$('txClock').textContent=fmt(current?audio.currentTime:0);$('txSeek').max=current&&Number.isFinite(audio.duration)?audio.duration:S.episodes[transcriptView]?.length||100;$('txSeek').value=current?audio.currentTime:0;if(!current||!transcriptFollow||$('txSearch').value)return;const time=audio.currentTime,rows=Array.from(box.querySelectorAll('[data-time]'));let active=null;for(const row of rows){if(Number(row.dataset.time)<=time)active=row;else break}if(active&&transcriptJob?.id===transcriptView&&time-Number(active.dataset.time)>18)active=null;if(active!==transcriptActive){transcriptActive?.classList.remove('tx-active');transcriptActive=active;if(active){active.classList.add('tx-active');const y=box.scrollTop+active.getBoundingClientRect().top-box.getBoundingClientRect().top-(box.clientHeight-active.offsetHeight)*.4;box.scrollTo({top:Math.max(0,y),behavior:'smooth'})}}}
function drawTranscript(id,record){if(transcriptView!==id||!$('txLines'))return;const q=$('txSearch').value.toLowerCase(),box=$('txLines'),previous=box.scrollTop;box.innerHTML=(record?.lines||[]).filter(l=>l.text.toLowerCase().includes(q)).map(l=>l.t===null?'<p>'+esc(l.text)+'</p>':'<button class="chapter" data-time="'+Number(l.t)+'" onclick="playTranscriptTime('+Number(l.t)+')"><small>'+fmt(l.t)+'</small> '+esc(l.text)+'</button>').join('')||'<p class="muted">No matching transcript text.</p>';$('txExport').disabled=!record?.lines?.length;$('txGenerate').disabled=!!transcriptJob;$('txCancel').hidden=transcriptJob?.id!==id;transcriptActive=null;if(!transcriptFollow||q)box.scrollTop=previous;followTranscript()}
async function openTranscript(id=S.current){if(!S.episodes[id]){toast('Choose an episode first');return}transcriptView=id;transcriptFollow=true;modal(`<div class="tx-header"><div><span class="tx-kicker">LIVE TRANSCRIPT</span><h2>${esc(S.episodes[id].title)}</h2></div></div><div class="tx-bar"><button id="txFollow" aria-pressed="true" onclick="toggleTranscriptFollow()">✓ Follow playback</button><button onclick="toggleTranscriptTools()">⋯</button></div><div id="txTools" hidden><div class="toolbar"><button id="txGenerate" onclick="generateTranscript(transcriptView)">Generate transcript</button><button id="txCancel" hidden onclick="cancelTranscript()">Cancel transcription</button><button id="txExport" disabled onclick="exportTranscript(transcriptView)">Export text</button></div><input id="txSearch" placeholder="Search transcript" oninput="refreshTranscriptView()"></div><p id="txStatus" role="status">Looking for transcript…</p><div class="transcript" id="txLines" aria-label="Episode transcript"></div><div class="tx-footer"><input id="txSeek" type="range" aria-label="Playback position" min="0" max="100" step="0.1" oninput="if(transcriptView===S.current&&audio.src)audio.currentTime=Number(this.value)"><div class="tx-controls"><button onclick="if(transcriptView===S.current)skip(-1)" aria-label="Skip backward">↶ ${S.settings.back}</button><button id="txPlay" class="primary" aria-label="Play" onclick="if(transcriptView===S.current)togglePlay();else playEpisode(transcriptView)">▶</button><button onclick="if(transcriptView===S.current)skip(1)" aria-label="Skip forward">${S.settings.forward} ↷</button><span id="txClock">0:00</span></div></div>`);$('modal').dataset.kind='transcript';let rec=await storedTranscript(id);if(transcriptView!==id||!$('txLines'))return;if(!rec&&S.episodes[id].transcript){try{const lines=parseTranscript(await fetchText(S.episodes[id].transcript));if(lines.length){rec={lines,source:'Publisher',complete:true};await putBlob(transcriptKey(id),rec)}}catch{}}if(transcriptJob?.id===id)rec=transcriptJob.record||rec;drawTranscript(id,rec);transcriptStatus(id,transcriptJob?.id===id?'Transcription running…':rec?rec.source+(rec.complete?' transcript':' — partial transcript'):'Preparing automatic transcription…');if(!rec?.complete&&!transcriptJob&&transcriptView===id&&$('txLines')&&$('modal').open)generateTranscript(id,true,rec)}
function toggleTranscriptFollow(){transcriptFollow=!transcriptFollow;$('txFollow').textContent=transcriptFollow?'✓ Follow playback':'Follow playback';$('txFollow').setAttribute('aria-pressed',String(transcriptFollow));transcriptActive?.classList.remove('tx-active');transcriptActive=null;followTranscript()}
function toggleTranscriptTools(){$('txTools').hidden=!$('txTools').hidden;if($('txTools').hidden&&$('txSearch').value){$('txSearch').value='';refreshTranscriptView()}}
async function refreshTranscriptView(){const id=transcriptView,rec=transcriptJob?.id===id?transcriptJob.record:await storedTranscript(id);drawTranscript(id,rec)}
function playTranscriptTime(t){const id=transcriptView;if(id===S.current&&audio.src){audio.currentTime=t;audio.play().catch(()=>{})}else playEpisode(id,t)}
async function exportTranscript(id){const rec=transcriptJob?.id===id?transcriptJob.record:await storedTranscript(id);if(rec?.lines?.length)downloadFile('podflow-transcript.txt',rec.lines.map(l=>(l.t===null?'':fmt(l.t)+' ')+l.text).join('\n'),'text/plain')}
function cancelTranscript(){const j=transcriptJob;if(j){j.cancelled=true;j.worker?.terminate();j.reject?.(Error('Cancelled'));transcriptStatus(j.id,'Cancelling…')}}
async function generateTranscript(id,automatic=false,existing=null){if(transcriptJob){transcriptStatus(id,'Another transcription is running.');return}const e=S.episodes[id];if(!e)return;if(!automatic&&!confirm('Generate an English AI transcript on this device? First use downloads a speech model. Keep PodFlow open; long episodes may exceed phone memory.'))return;
const job={id,cancelled:false,record:existing?.source==='AI-generated'?existing:{source:'AI-generated',complete:false,lines:[],completedChunks:[]}};job.record.completedChunks??=[];transcriptJob=job;drawTranscript(id,job.record);let ctx;
try{transcriptStatus(id,'Reading episode audio…');let blob=await getBlob(id);if(!blob){if(!e.url)throw Error('No audio available');const res=await fetch(e.url,{credentials:'omit'});if(!res.ok)throw Error('Audio unavailable');blob=await res.blob()}if(job.cancelled)throw Error('Cancelled');const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Audio decoding is unsupported');ctx=new AC({sampleRate:16000});const decoded=await ctx.decodeAudioData(await blob.arrayBuffer());blob=null;const rate=decoded.sampleRate;const duration=decoded.duration;const channels=Array.from({length:decoded.numberOfChannels},(_,i)=>decoded.getChannelData(i));job.worker=new Worker('./transcribe-worker.js?v=12',{type:'module'});
const chunkSize=15;let pending=Array.from({length:Math.ceil(duration/chunkSize)},(_,i)=>i*chunkSize).filter(t=>!job.record.completedChunks.includes(t));if(!job.record.completedChunks.length)job.record.lines=[];while(pending.length){if(job.cancelled)throw Error('Cancelled');const playhead=S.current===id?audio.currentTime:0;const target=Math.floor(playhead/chunkSize)*chunkSize;let index=pending.indexOf(target);if(index<0){index=pending.findIndex(t=>t>=target);if(index<0)index=0}const start=pending.splice(index,1)[0];const end=Math.min(duration,start+chunkSize);const samples=new Float32Array(Math.ceil((end-start)*16000));for(let i=0;i<samples.length;i++){const pos=Math.min(decoded.length-1,Math.floor((start+i/16000)*rate));let v=0;for(const ch of channels)v+=ch[pos];samples[i]=v/channels.length}transcriptStatus(id,'Transcribing '+fmt(start)+' of '+fmt(duration)+'…');const lines=await new Promise((resolve,reject)=>{job.reject=reject;job.worker.onmessage=({data})=>{if(data.status)transcriptStatus(id,data.status);else if(data.error)reject(Error(data.error));else resolve(data.lines)};job.worker.onerror=()=>reject(Error('Speech model could not start'));job.worker.postMessage({samples,offset:start},[samples.buffer])});job.record.lines.push(...lines.filter(l=>l.text));job.record.lines.sort((a,b)=>a.t-b.t);job.record.completedChunks.push(start);await putBlob(transcriptKey(id),job.record);drawTranscript(id,job.record)}
job.record.complete=true;await putBlob(transcriptKey(id),job.record);transcriptStatus(id,'AI transcript complete. Review for accuracy.');toast('Transcript ready');
}catch(err){transcriptStatus(id,job.cancelled?'Cancelled. Completed portions are saved.':'Transcription failed: '+(err.message||err)+'. Try a downloaded episode or a computer.');toast(job.cancelled?'Transcription cancelled':'Transcription could not finish')}finally{job.worker?.terminate();if(ctx)try{await ctx.close()}catch{}transcriptJob=null;drawTranscript(id,job.record)}}

let detailId=null;function jump(t){if(detailId&&detailId!==S.current)playEpisode(detailId,t);else if(audio.src)audio.currentTime=t}
async function openDetails(id=S.current){let e=S.episodes[id];if(!e){toast('Choose an episode first');return}detailId=id;modal(`<h2>${esc(e.title)}</h2><div class="section">${sanitizedHTML(e.notes)||'<p class="muted">No show notes.</p>'}</div><h3>Chapters</h3><div id="chapters" class="section">${e.chapters?'Loading…':'No creator-provided JSON chapters.'}</div><h3>Transcript</h3><button onclick="openTranscript('${id}')">Open / Generate transcript</button><input placeholder="Search transcript" style="width:100%;margin:10px 0" oninput="document.querySelectorAll('#transcript > *').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(this.value.toLowerCase()))"><div id="transcript" class="transcript">${e.transcript?'Loading…':'No creator-provided transcript.'}</div>`);if(e.chapters)try{let j=JSON.parse(await fetchText(e.chapters));if(detailId===id&&$('chapters'))$('chapters').innerHTML=(j.chapters||[]).map(c=>`<button class="chapter" onclick="jump(${Number(c.startTime)||0})">${fmt(c.startTime)} • ${esc(c.title||'Chapter')}</button>`).join('')}catch{if($('chapters'))$('chapters').textContent='Chapters unavailable (network or CORS).'}if(e.transcript)try{let t=await fetchText(e.transcript);if(detailId!==id||!$('transcript'))return;let lines;try{let j=JSON.parse(t);lines=(j.segments||[]).map(x=>({t:Number(x.startTime??x.start)||0,text:x.body||x.text||''}))}catch{lines=t.replace(/\r/g,'').split(/\n\s*\n/).filter(Boolean).map(x=>{let m=x.match(/((?:\d+:)?\d+:\d+)[.,]\d+\s*-->/);return {t:m?seconds(m[1]):null,text:m?x.split('\n').filter(l=>!l.includes('-->')&&!/^\d+$/.test(l)).join(' '):x}})}$('transcript').innerHTML=lines.map(l=>l.t===null?`<p>${esc(l.text)}</p>`:`<button onclick="jump(${l.t})">${fmt(l.t)} • ${esc(l.text)}</button>`).join('')}catch{if($('transcript'))$('transcript').textContent='Transcript unavailable (network or CORS).'}}
let dbPromise;function db(){return dbPromise??=new Promise((resolve,reject)=>{let r=indexedDB.open('podflow-audio',1);r.onupgradeneeded=()=>r.result.createObjectStore('audio');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}async function dbOp(mode,fn){let d=await db();return new Promise((resolve,reject)=>{let tx=d.transaction('audio',mode),r=fn(tx.objectStore('audio'));tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}const getBlob=id=>dbOp('readonly',s=>s.get(id));const putBlob=(id,b)=>dbOp('readwrite',s=>s.put(b,id));const delBlob=id=>dbOp('readwrite',s=>s.delete(id));let downloading=new Set(),downloadProgress={};
async function downloadEpisode(id,quiet=false){
let e=S.episodes[id];if(!e?.url||downloading.has(id)||S.downloads[id])return;
downloading.add(id);downloadProgress[id]='…';render();if(!quiet)toast('Downloading episode. Keep PodFlow open.');
try{
if(navigator.storage?.persist)try{await navigator.storage.persist()}catch{}
let r=await fetch(e.url,{credentials:'omit'});if(!r.ok||r.status===206)throw Error('Audio request failed');
let type=r.headers.get('content-type')||'application/octet-stream';if(/text\/html|application\/json|text\/xml/i.test(type))throw Error('Not an audio file');
let b;if(r.body?.getReader){let reader=r.body.getReader(),chunks=[],received=0,total=Number(r.headers.get('content-length'))||0,last=0;while(true){let {done,value}=await reader.read();if(done)break;chunks.push(value);received+=value.byteLength;if(Date.now()-last>500){downloadProgress[id]=total?Math.min(99,Math.floor(received/total*100))+'%':(received/1048576).toFixed(1)+' MB';last=Date.now();if(!quiet)toast('Downloading '+downloadProgress[id]);render()}}b=new Blob(chunks,{type})}else b=await r.blob();
if(!b.size)throw Error('Empty audio');await putBlob(id,b);S.downloads[id]={date:Date.now(),size:b.size};save();await retention(e.show);if(!quiet)toast(S.downloads[id]?'Download complete — ready for offline listening':'Download removed by show retention settings');
}catch{if(!quiet)toast('Download failed. The audio host may block browser downloads, or device storage may be full.')}finally{downloading.delete(id);delete downloadProgress[id];render()}}
async function removeDownload(id){if(!S.episodes[id]?.url){toast('Local files cannot be removed through this action.');return}if(id===S.current){toast('Choose another episode before removing this download.');return}try{await delBlob(id);delete S.downloads[id];save();render()}catch{toast('Could not remove download')}}async function retention(show){let n=S.shows[show]?.settings?.keep;if(!n)return;let es=Object.values(S.episodes).filter(e=>e.show===show&&S.downloads[e.id]).sort((a,b)=>b.date-a.date);for(let e of es.slice(n))if(e.id!==S.current)await removeDownload(e.id)}async function cleanup(){if(!S.settings.cleanup)return;for(let id of Object.keys(S.downloads))if(id!==S.current&&S.played[id]&&Date.now()-S.played[id]>86400000)await removeDownload(id)}function prefetch(){if(S.settings.autoDownload&&navigator.connection?.type==='wifi'&&S.queue.length)downloadEpisode(S.queue[0],true)}setInterval(cleanup,60000);
function pick(accept,cb){let f=$('file');f.accept=accept;f.value='';f.onchange=()=>{if(f.files[0])cb(f.files[0])};f.click()}function localAudio(){pick('audio/*,.mp3,.m4a,.wav,.ogg',async f=>{let id=idFor(f.name+'|'+f.size+'|'+f.lastModified);try{await putBlob(id,f);S.episodes[id]={id,title:f.name,show:'local',date:Date.now(),length:0,notes:''};S.downloads[id]={date:Date.now(),size:f.size};save();render();playEpisode(id)}catch{toast('Local file storage failed')}})}function directAudio(){modal('<h2>Add audio URL</h2><form class="settings section" onsubmit="event.preventDefault();addDirect(this)"><input name="title" placeholder="Episode title" required><input name="url" type="url" placeholder="https://…/episode.mp3" required><button class="primary">Add episode</button></form>')}function addDirect(f){let url=safeURL(f.url.value);if(!url)return;let id=idFor(url);S.episodes[id]={id,title:f.title.value,url,show:'local',date:Date.now(),length:0,notes:''};save();closeModal();render();playEpisode(id)}function downloadFile(name,text,type){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function exportOPML(){downloadFile('podflow.opml','<?xml version="1.0" encoding="UTF-8"?><opml version="2.0"><head><title>PodFlow subscriptions</title></head><body>'+Object.values(S.shows).filter(s=>s.feed).map(s=>`<outline type="rss" text="${esc(s.title)}" title="${esc(s.title)}" xmlUrl="${esc(s.feed)}"/>`).join('')+'</body></opml>','text/xml')}function importOPML(){pick('.opml,.xml',async f=>{let x=new DOMParser().parseFromString(await f.text(),'application/xml'),urls=Array.from(x.querySelectorAll('outline[xmlUrl]')).map(n=>n.getAttribute('xmlUrl'));if(!urls.length){toast('No RSS subscriptions found');return}for(let url of urls)await subscribe(url);toast('OPML import completed. Check library for successful feeds.')})}function backup(){downloadFile('podflow-backup.json',JSON.stringify({...S,downloads:{}}),'application/json')}function restore(){pick('.json',async f=>{try{let j=JSON.parse(await f.text());if(!j.shows||!j.episodes||!Array.isArray(j.queue))throw Error();if(!confirm('Replace your library and playback history with this backup?'))return;audio.pause();audio.removeAttribute('src');audio.load();S={...structuredClone(defaults),...j,settings:{...defaults.settings,...j.settings},downloads:{}};save();location.reload()}catch{toast('Invalid backup')}})}
let pullStart=null,pullDistance=0,pullRunning=false;
const pullIndicator=$('pullIndicator');
function pullAllowed(){return !pullRunning&&!busy&&!$('modal').open&&!document.body.classList.contains('now-expanded')&&!document.body.classList.contains('driving')&&window.scrollY<=1}
function showPull(distance,message){pullIndicator.hidden=false;pullIndicator.style.transform='translate(-50%, '+Math.min(90,distance)+'px)';pullIndicator.textContent=message}
function resetPull(){pullStart=null;pullDistance=0;if(!pullRunning){pullIndicator.hidden=true;pullIndicator.style.transform='translate(-50%,0)'}}
async function pullRefresh(){if(pullRunning||busy)return;pullRunning=true;showPull(65,'↻ Refreshing…');try{if(navigator.onLine===false){render();toast('Offline — showing saved episodes');return}const ids=page==='Library'&&selectedShow?[selectedShow]:['Home','Library','Episodes'].includes(page)?Object.keys(S.shows):[];let ok=0,fail=0;for(const id of ids){const show=S.shows[id];if(show?.feed){if(await subscribe(show.feed,show,true,true))ok++;else fail++}}render();toast(fail?('Refreshed '+ok+' feeds; '+fail+' unavailable.'):ids.length?'Episodes refreshed':'Screen refreshed')}catch{toast('Refresh failed — saved episodes are unchanged')}finally{pullRunning=false;resetPull()}}
document.addEventListener('touchstart',e=>{if(e.touches.length!==1||!pullAllowed()||e.target.closest('button,input,select,textarea,a,dialog,.nav,.player')){resetPull();return}pullStart={x:e.touches[0].clientX,y:e.touches[0].clientY};pullDistance=0},{passive:true});
document.addEventListener('touchmove',e=>{if(!pullStart||pullRunning)return;if(e.touches.length!==1){resetPull();return}const t=e.touches[0],dy=t.clientY-pullStart.y,dx=t.clientX-pullStart.x;if(dy<0||Math.abs(dx)>Math.max(15,dy)||window.scrollY>1){resetPull();return}if(dy<12)return;if(e.cancelable)e.preventDefault();pullDistance=dy;showPull(dy*.55,dy>=100?'↑ Release to refresh':'↓ Pull to refresh')},{passive:false});
document.addEventListener('touchend',()=>{const trigger=pullStart&&pullDistance>=100;resetPull();if(trigger)pullRefresh()},{passive:true});
document.addEventListener('touchcancel',resetPull,{passive:true});
render();if(S.current&&S.episodes[S.current])playEpisode(S.current,undefined,false);cleanup();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
